UPDATE places SET name_english=place_name,state_name=(SELECT s.state_name FROM cities c JOIN states s ON s.id=c.state_id WHERE c.id=places.city_id),created_at='2026-10-02',updated_at='2026-10-02',verification_status='partial',verification_notes='Identity/source checked; live/provider metadata not fetched.',verified_at='2026-10-02' WHERE id BETWEEN 8000001 AND 8000117;
UPDATE places SET source=CASE city_id WHEN 80001 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Tirana destination/attraction pages; checked 2026-10-02' WHEN 80003 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Gjirokastër destination/attraction pages; checked 2026-10-02' WHEN 80004 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Shkodër destination/attraction pages; checked 2026-10-02' WHEN 80007 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Durrës destination/attraction pages; checked 2026-10-02' WHEN 80008 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Vlorë destination/attraction pages; checked 2026-10-02' WHEN 80009 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Sarandë destination/attraction pages; checked 2026-10-02' WHEN 80010 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Korçë destination/attraction pages; checked 2026-10-02' WHEN 80011 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Përmet destination/attraction pages; checked 2026-10-02' WHEN 80012 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Pogradec destination/attraction pages; checked 2026-10-02' WHEN 80013 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Himarë destination/attraction pages; checked 2026-10-02' WHEN 80005 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Theth destination/attraction pages; checked 2026-10-02' WHEN 80006 THEN 'Albanian National Tourism Agency official tourism portal (akt.gov.al), Krujë destination/attraction pages; checked 2026-10-02' WHEN 80002 THEN 'Albanian National Tourism Agency (akt.gov.al) and Berat municipal tourism portal (berat.al); checked 2026-10-02' END WHERE id BETWEEN 8000001 AND 8000117;
INSERT INTO opening_hours (id,place_id,notes) SELECT id,id,'Exact weekly hours require official/operator/provider refresh; not guessed.' FROM places WHERE id BETWEEN 8000001 AND 8000117;
INSERT INTO photos (id,place_id,photo_title,usage_terms,photo_status) SELECT id,id,place_name,'no-photo-available','no_match' FROM places WHERE id BETWEEN 8000001 AND 8000117;
